def step(kind,selector='',tag='',value='',label='',type_='',timeout=1200):
    s={'kind':kind,'route':ROUTE,'label':kind,'value':value,'timeout':timeout}
    if selector:s.update(selector=selector,fingerprint={'tag':tag,'role':'','type':type_,'label':label})
    return s

def suite(name,steps):return {'id':name,'module':'appointment','name':name,'steps':steps}

